    @inline(__always)
    private func checkHalfVectorClampingRoundingShiftedRightByFromUInt16UncheckedConstantBits(
        _ bits: Int
    ) {
        let mismatches = Mismatches(
            "halfVectorClampingRoundingShiftedRightByFromUInt16 unchecked with bits \(bits)"
        )
        let aInputs = Inputs.integerDemotions(
            SIMDUInt16.Vector.self,
            to: H.Lane.self,
            seed: 0x1C47_9FDC_0430_DC0E
        )
        for a in aInputs {
            mismatches.check(
                unsafe H.halfVector(clamping: a, roundingShiftedRightByUnchecked: bits),
                H.HalfVector(
                    raw: HighwayReference.halfVectorClampingRoundingShiftedRightByU16ToU8(
                        a.raw,
                        Int32(truncatingIfNeeded: bits)
                    )
                ),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

